'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const W=1200,H=530,ground=424,cannon={x:106,y:402};
let phase='aim',angle=45,power=0,charge=0,total=0,best=0,level=1,shot=0,mult=1,hits=0,ball=null,trail=[],particles=[],labels=[],drag=false,last=0,time=0,shotTime=0,toastTime=0,sound=false,audio;
const surfaces=[{x:266,y:424,w:109,h:18,type:'score',label:'+100'},{x:427,y:424,w:112,h:18,type:'double',label:'×2'},{x:590,y:412,w:92,h:30,type:'slime',label:'BOUNCE'},{x:758,y:424,w:90,h:18,type:'sticky',label:'DANGER'},{x:938,y:424,w:136,h:18,type:'score',label:'+300',points:300},{x:447,y:258,w:180,h:30,type:'island',label:'+150'},{x:817,y:190,w:171,h:30,type:'island',label:'+150'}];
const colors={score:'#d76450',double:'#e0a047',slime:'#96c656',sticky:'#80618f',island:'#78a655'};
function tone(freq,duration=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.start();o.stop(audio.currentTime+duration)}catch{}}
function hud(){$('total').textContent=total.toLocaleString();$('shot').innerHTML=shot.toLocaleString()+' <small>pt</small>';$('combo').textContent='×'+mult;$('bounces').textContent=hits+' BOUNCES';$('best').innerHTML=best.toLocaleString()+' <small>pt</small>';$('lv').textContent='LV. '+level;$('levelname').textContent=['見習いの大砲','青銅の大砲','草原の名砲','天空の大砲','伝説の大砲'][Math.min(level-1,4)];const base=250*(level-1)*level,next=250*level*(level+1);$('xp').style.width=(total-base)/(next-base)*100+'%';$('nextlevel').textContent='次のレベルまで '+(next-total).toLocaleString()+' pt';$('angle').textContent=Math.round(angle)}
function announce(t){$('toast').textContent=t;toastTime=2}
function scoreHit(s,x,y){hits++;if(s.type==='double')mult=Math.min(32,mult*2);const pts=(s.points||({score:100,double:50,slime:75,island:150}[s.type]||20))*mult;shot+=pts;labels.push({x,y,text:s.type==='double'?'×'+mult+'  +'+pts:'+'+pts,t:1.5});for(let i=0;i<9;i++)particles.push({x,y,vx:(Math.random()-.5)*170,vy:-Math.random()*160,t:.7,color:colors[s.type]||'#fff1b7'});tone(330+Math.min(hits,12)*65);hud()}
function startCharge(){if(phase!=='aim')return;phase='charge';charge=0;$('hint').textContent='金色のタイミングでタップして発射！';$('action').innerHTML='タップで発射 <span>↗</span>';tone(240)}
function fire(){if(phase!=='charge')return;const perfect=power>=.83&&power<=.94;const speed=(280+power*470)*(1+Math.min(level-1,12)*.045),a=angle*Math.PI/180;ball={x:cannon.x+Math.cos(a)*61,y:cannon.y-Math.sin(a)*61,vx:Math.cos(a)*speed,vy:-Math.sin(a)*speed,r:9,rest:0};phase='flight';shotTime=0;trail=[];$('action').textContent='ボールを見守ろう';$('action').disabled=true;$('hint').textContent='バウンドをつないで、点数アップ！';if(perfect){mult=2;announce('PERFECT!  ×2 START');hud()}tone(100,.22)}
function finish(reason){if(phase!=='flight')return;phase='result';total+=shot;best=Math.max(best,shot);const prev=level;while(total>=250*level*(level+1))level++;$('resultreason').textContent=reason;$('resultscore').textContent=shot.toLocaleString();$('resultdetail').textContent=level>prev?'LEVEL UP! LV. '+level+' — 発射力アップ':hits+' 回のバウンド · 最大 ×'+mult;$('result').hidden=false;$('hint').textContent='次は、どんな軌道を描こう？';hud()}
function next(){if(phase!=='result')return;phase='aim';ball=null;trail=[];shot=0;mult=1;hits=0;power=0;$('result').hidden=true;$('action').disabled=false;$('action').innerHTML='角度を決める <span>→</span>';$('hint').textContent='画面をドラッグして、狙いをさだめよう';hud()}
function aim(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;angle=Math.max(12,Math.min(82,Math.atan2(cannon.y-y,Math.max(8,x-cannon.x))*180/Math.PI));hud()}
canvas.addEventListener('pointerdown',e=>{canvas.focus();if(phase==='charge'){fire();return}if(phase!=='aim')return;drag=true;canvas.setPointerCapture(e.pointerId);aim(e)});canvas.addEventListener('pointermove',e=>{if(drag&&phase==='aim')aim(e)});canvas.addEventListener('pointerup',()=>{if(drag){drag=false;startCharge()}});canvas.addEventListener('pointercancel',()=>drag=false);
$('action').onclick=()=>phase==='aim'?startCharge():phase==='charge'?fire():null;$('again').onclick=next;$('help').onclick=()=>$('instructions').showModal();$('closehelp').onclick=()=>$('instructions').close();$('sound').onclick=()=>{sound=!sound;$('sound').textContent='音 '+(sound?'ON':'OFF');tone(440)};
document.addEventListener('keydown',e=>{if($('instructions').open||e.target.tagName==='BUTTON')return;if(['ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();if(phase==='aim'&&e.key.startsWith('Arrow')){angle=Math.max(12,Math.min(82,angle+(e.key==='ArrowLeft'?2:-2)));hud()}if(e.key===' '&&!e.repeat){if(phase==='aim')startCharge();else if(phase==='charge')fire()}if(e.key==='Enter')next()});
function rr(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function text(t,x,y,size,color='#fff8e7'){ctx.fillStyle=color;ctx.font='800 '+size+'px "Noto Sans JP", sans-serif';ctx.textAlign='center';ctx.fillText(t,x,y)}
function landscape(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#c7e4de');sky.addColorStop(.8,'#edf0c9');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ellipse(970,77,35,35,'#fff6cd');for(const [x,y,s]of [[205,83,1],[653,57,.8],[1094,132,.7]]){ellipse(x,y,48*s,12*s,'#f9fcf1a0');ellipse(x-17*s,y-9*s,25*s,16*s,'#f9fcf1a0');ellipse(x+18*s,y-6*s,28*s,18*s,'#f9fcf1a0')}
ctx.fillStyle='#aecbb1';ctx.beginPath();ctx.moveTo(0,325);ctx.bezierCurveTo(180,125,300,360,480,285);ctx.bezierCurveTo(710,135,780,310,960,257);ctx.bezierCurveTo(1080,221,1110,255,1200,250);ctx.lineTo(1200,440);ctx.lineTo(0,440);ctx.fill();ctx.fillStyle='#91b38d';ctx.beginPath();ctx.moveTo(0,367);ctx.bezierCurveTo(200,270,292,324,440,366);ctx.bezierCurveTo(690,429,745,276,1000,340);ctx.lineTo(1200,310);ctx.lineTo(1200,440);ctx.lineTo(0,440);ctx.fill();
ctx.globalAlpha=.4;ctx.fillStyle='#769585';ctx.fillRect(1028,248,67,80);for(let i=0;i<4;i++)ctx.fillRect(1028+i*19,237,10,15);ctx.fillRect(1053,218,21,110);ctx.beginPath();ctx.moveTo(1050,218);ctx.lineTo(1064,197);ctx.lineTo(1078,218);ctx.fill();ctx.globalAlpha=1;
for(const [x,y,s] of [[36,351,1],[1120,351,1.2],[715,381,.55],[193,364,.65]]){ctx.fillStyle='#7b8860';ctx.fillRect(x-4*s,y,8*s,57*s);ellipse(x,y-4*s,27*s,36*s,'#75966c');ellipse(x-19*s,y+11*s,20*s,25*s,'#7f9f6a');ellipse(x+18*s,y+10*s,22*s,27*s,'#89aa72')}
ctx.fillStyle='#88ad5c';ctx.fillRect(0,421,W,109);ctx.fillStyle='#749751';ctx.fillRect(0,435,W,95);ctx.fillStyle='#678647';ctx.fillRect(0,481,W,49);for(let i=0;i<110;i++){const x=(i*137)%1200,y=447+(i*31)%75;ctx.fillStyle=i%3?'#8ba45b':'#a7b770';ctx.fillRect(x,y,3,2)}for(let i=0;i<85;i++){const x=(i*97)%1200;ctx.strokeStyle='#668e45';ctx.beginPath();ctx.moveTo(x,425);ctx.lineTo(x-3,416-i%6);ctx.moveTo(x,425);ctx.lineTo(x+4,418);ctx.stroke()}for(const x of [218,391,700,893,1103]){ctx.strokeStyle='#618d43';ctx.beginPath();ctx.moveTo(x,422);ctx.lineTo(x,410);ctx.stroke();ellipse(x,408,3,3,'#f7e1a0')}
}
function platform(s){const c=colors[s.type];if(s.type==='island'){ctx.fillStyle='#8c9270';ctx.beginPath();ctx.moveTo(s.x,s.y+8);ctx.lineTo(s.x+22,s.y+48);ctx.lineTo(s.x+61,s.y+57);ctx.lineTo(s.x+91,s.y+43);ctx.lineTo(s.x+s.w-19,s.y+35);ctx.lineTo(s.x+s.w,s.y);ctx.fill();rr(s.x,s.y,s.w,s.h,8,'#9b9875');rr(s.x-3,s.y-5,s.w+6,12,6,'#8eb968');ctx.strokeStyle='#bed98c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(s.x+10,s.y-2);ctx.lineTo(s.x+s.w-10,s.y-2);ctx.stroke();text(s.label,s.x+s.w/2,s.y+22,17);text('↕',s.x+s.w/2,s.y+44,14,'#d7dfb0')}
else if(s.type==='slime'){ellipse(s.x+s.w/2,s.y+19,s.w/2,24,c);ellipse(s.x+25,s.y+5,12,5,'#d1ec8f');ellipse(s.x+35,s.y+14,3,4,'#426f39');ellipse(s.x+58,s.y+14,3,4,'#426f39');text('↑↑',s.x+s.w/2,s.y-15,20,'#638f3b')}
else{rr(s.x,s.y,s.w,s.h,5,c);ellipse(s.x+s.w/2,s.y+4,s.w*.4,7,s.type==='sticky'?'#594266':'#ffffff22');text(s.label,s.x+s.w/2,s.y-12,s.type==='sticky'?13:26,s.type==='sticky'?'#765687':c);if(s.type==='sticky'){for(let i=0;i<5;i++)ellipse(s.x+12+i*16,s.y+5+Math.sin(time*2+i)*3,4,3,'#b598c0')}else{ctx.strokeStyle='#ffffff77';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(s.x+s.w/2,s.y+6,s.w*.27,5,0,0,Math.PI*2);ctx.stroke()}}}
function drawCannon(){const a=angle*Math.PI/180;ellipse(cannon.x,428,50,8,'#365b3433');ctx.save();ctx.translate(cannon.x,cannon.y);ctx.rotate(-a);rr(-12,-16,75,32,8,'#314b47');rr(8,-18,11,36,3,'#b29c61');rr(50,-19-power*6,16+power*6,38+power*12,5,'#587167');rr(52,-13-power*4,13+power*6,26+power*8,4,'#233b37');ctx.restore();rr(77,402,55,17,5,'#9d7847');ellipse(103,411,23,23,'#715834');ellipse(103,411,18,18,'#b19258');ctx.strokeStyle='#775e38';ctx.lineWidth=4;for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(103,411);ctx.lineTo(103+Math.cos(i*Math.PI/3)*16,411+Math.sin(i*Math.PI/3)*16);ctx.stroke()}ellipse(103,411,6,6,'#dfbe78');if(phase==='aim'||phase==='charge'){const v=phase==='charge'?280+power*470:560;ctx.fillStyle='#fff9e4aa';for(let i=1;i<17;i++){const t=i*.057,x=cannon.x+Math.cos(a)*(61+v*t),y=cannon.y-Math.sin(a)*(61+v*t)+.5*440*t*t;if(y>416)break;ellipse(x,y,Math.max(1,3-i*.1),Math.max(1,3-i*.1),'#fff9e4bb')}}}
function update(dt){if($('instructions').open)return;if(phase==='charge'){charge+=dt;power=(1-Math.cos(charge*2.7))/2}$('powerfill').style.width=power*100+'%';$('needle').style.left=power*99+'%';$('powertext').textContent=phase==='aim'?'角度を決めよう':Math.round(power*100)+'%'+(power>=.83&&power<=.94?' · PERFECT':'');
if(phase==='flight'&&ball){shotTime+=dt;const steps=Math.ceil(dt/.006),d=dt/steps;for(let i=0;i<steps&&phase==='flight';i++){const b=ball,px=b.x,py=b.y;b.vy+=440*d;b.x+=b.vx*d;b.y+=b.vy*d;for(const s of surfaces){if(b.x+b.r<=s.x||b.x-b.r>=s.x+s.w||b.y+b.r<=s.y||b.y-b.r>=s.y+s.h)continue;if(s.type==='sticky'){finish('粘着トラップ！ 獲得ポイントはキープ');break}if(py+b.r<=s.y+.5&&b.vy>0){b.y=s.y-b.r;b.vy=-Math.max(s.type==='slime'?470:125,Math.abs(b.vy)*(s.type==='slime'?1.22:.79));b.vx*=.96;scoreHit(s,b.x,b.y-18)}else if(py-b.r>=s.y+s.h-.5&&b.vy<0){b.y=s.y+s.h+b.r;b.vy=Math.abs(b.vy)*.86;scoreHit(s,b.x,b.y+20)}else if(px+b.r<=s.x+.5&&b.vx>0){b.x=s.x-b.r;b.vx=-b.vx*.83;scoreHit(s,b.x,b.y)}else if(px-b.r>=s.x+s.w-.5&&b.vx<0){b.x=s.x+s.w+b.r;b.vx=-b.vx*.83;scoreHit(s,b.x,b.y)}}if(phase!=='flight')break;if(b.y+b.r>=ground&&b.vy>0){b.y=ground-b.r;if(Math.abs(b.vy)>55){b.vy=-b.vy*.57;b.vx*=.8;scoreHit({type:'grass'},b.x,b.y-10)}else{b.vy=0;b.vx*=Math.pow(.03,d);b.rest+=d;if(b.rest>.7)finish('草原に着地！')}}if(b.x>W+70||b.x< -70||b.y>H+100)finish('遠くまで飛んだ！');if(shotTime>22)finish('ナイスコンボ！')}if(ball){trail.push({x:ball.x,y:ball.y});if(trail.length>35)trail.shift()}}
particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.t-=dt});particles=particles.filter(p=>p.t>0);labels.forEach(p=>{p.y-=28*dt;p.t-=dt});labels=labels.filter(p=>p.t>0);if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').textContent=''}}
function render(){ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);landscape();surfaces.forEach(platform);drawCannon();trail.forEach((p,i)=>ellipse(p.x,p.y,2+i/18,2+i/18,'#fffbe4'+Math.round(i/trail.length*130).toString(16).padStart(2,'0')));if(ball){ellipse(ball.x+2,ball.y+3,10,10,'#35474133');ellipse(ball.x,ball.y,9,9,'#354540');ellipse(ball.x-3,ball.y-3,3,3,'#b8c6b8');ellipse(ball.x+2,ball.y-1,1.3,1.3,'#fff');ellipse(ball.x+6,ball.y-1,1.3,1.3,'#fff')}particles.forEach(p=>{ctx.globalAlpha=Math.min(1,p.t*2);ellipse(p.x,p.y,3,3,p.color)});ctx.globalAlpha=1;labels.forEach(p=>{ctx.globalAlpha=Math.min(1,p.t);text(p.text,p.x,p.y,22,'#fff5b8')});ctx.globalAlpha=1}
function frame(ts){const dt=Math.min(.04,(ts-last)/1000||.016);last=ts;time+=dt;update(dt);render();requestAnimationFrame(frame)}new ResizeObserver(()=>{const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}).observe(canvas);hud();requestAnimationFrame(frame);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_game_state',description:'Read the current cannon angle, shot, score and level.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({phase,angle,total,shot,level,mult,hits})})).catch(()=>{})}catch{}}
